select jsonb_agg(t order by t.schema,t.name,t.args) as functions from (select n.nspname as schema,p.proname as name,pg_get_function_identity_arguments(p.oid) as args,md5(p.prosrc) as md5 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','app_private') and (p.proname like '%activity%' or p.proname in ('require_superadmin_internal_context','has_platform_permission')))t;
